import sys

def find_centroids(n, parents, queries):
    from collections import defaultdict

    tree = defaultdict(list)
    for i, p in enumerate(parents, start=2):
        tree[p].append(i)

    size = [0] * (n + 1)
    centroid = [0] * (n + 1)

    def dfs(node):
        size[node] = 1
        max_subtree_size = 0
        for child in tree[node]:
            dfs(child)
            size[node] += size[child]
            if size[child] > max_subtree_size:
                max_subtree_size = size[child]

        remaining_size = size[1] - size[node]
        if 2 * max(max_subtree_size, remaining_size) <= size[1]:
            centroid[node] = node

    dfs(1)

    def find_subtree_centroid(node):
        total_size = size[node]
        for child in tree[node]:
            if size[child] * 2 > total_size:
                return find_subtree_centroid(child)
        return centroid[node]

    result = []
    for v in queries:
        if size[v] == 1:
            result.append(v)
        else:
            result.append(find_subtree_centroid(v))

    return result

input = sys.stdin.read().split()
n = int(input[0])
q = int(input[1])
parents = list(map(int, input[2:n+1]))
queries = list(map(int, input[n+1:]))

centroids = find_centroids(n, parents, queries)
print(' '.join(map(str, centroids)))
